/* Original vector scenery: eight distinct locations, no character images. */
function sceneWindows(x,y,cols,rows,dx=38,dy=36,color='#e9cfa0'){
 return Array.from({length:rows},(_,r)=>Array.from({length:cols},(_,c)=>`<rect x="${x+c*dx}" y="${y+r*dy}" width="${dx*.43}" height="${dy*.55}" rx="1" fill="${color}" opacity="${.45+(c+r)%3*.17}"/>`).join('')).join('');
}
function sceneTree(x,y,size=1,color='#527a67'){
 return `<g transform="translate(${x} ${y}) scale(${size})"><path d="M0 0V-140m0 70-30-40m30 15 30-42" fill="none" stroke="#526452" stroke-width="12"/><g fill="${color}"><ellipse cx="-32" cy="-123" rx="48" ry="39"/><ellipse cx="29" cy="-144" rx="48" ry="43"/><ellipse cy="-180" rx="50" ry="47"/></g></g>`;
}
function sceneHouse(x,y,w=155,h=155,color='#a6a58e'){
 return `<g><path d="M${x} ${y}v-${h}h${w}v${h}Z" fill="${color}"/><path d="M${x-18} ${y-h}l${w/2+18}-${w*.43} ${w/2+18} ${w*.43}Z" fill="#566c76"/><path d="M${x+w*.65} ${y}v-${h*.48}h${w*.18}v${h*.48}" fill="#536b69"/>${sceneWindows(x+20,y-h+22,3,2,40,42)}<path d="M${x+8} ${y-h+10}h${w-16}" stroke="#d0c6ac" stroke-width="5"/></g>`;
}
function sceneLantern(x,y){return `<g stroke="#455965" stroke-width="5" fill="none"><path d="M${x} 700V${y}q0-18 18-18h25"/><path d="M${x+27} ${y-16}h27l-5 13h-17Z" fill="#f6dca1" stroke-width="3"/></g>`;}
function regionScene(id){
 const palettes={1:['#9cbdc6','#e8cfa5'],2:['#a6c5d0','#e4d9b6'],3:['#9fb8c1','#dbbd9d'],4:['#a3b9ce','#e8c7a2'],5:['#8bb6ae','#c9d4a2'],6:['#96c7ca','#e3dbb3'],7:['#91baca','#efd1a2'],8:['#8faac6','#dcc4bb']};
 const [sky,horizon]=palettes[id]||palettes[5];
 const distant=`<path d="M0 380V285h45v-28h48v53h30v-86h63v65h35v-37h72v56h60v-65h53v38h50v-95h67v100h45v-45h74v60h60v-92h48v62h44v-80h55v112h56v-45h90v92Z" fill="#718d91" opacity=".4"/>`;
 let scene='';
 if(id===1)scene=`<path d="M0 450 490 370 1000 435V700H0Z" fill="#b1b2a0"/><path d="m390 700 80-300h36l150 300" fill="#727d7b"/><path d="m505 430 77 270" stroke="#ddd7b2" stroke-width="4" stroke-dasharray="35 25"/>${sceneHouse(-30,500,190,185,'#bfb397')}${sceneHouse(190,450,150,150,'#adb9a4')}${sceneHouse(635,455,180,170,'#b3a796')}${sceneHouse(840,505,180,200,'#8caca4')}${sceneTree(345,455,.6)}${sceneTree(800,505,.85)}${sceneLantern(370,340)}<path d="M25 540h320m290 0h365" stroke="#d5c7a8" stroke-width="10"/><path d="M40 700V550m35 150V550m35 150V550m35 150V550m35 150V550" stroke="#6f8075" stroke-width="5"/>`;
 if(id===2)scene=`<path d="M0 440H1000V700H0Z" fill="#acb8a8"/><path d="M80 250h840v220H80Z" fill="#a8a390"/><path d="M70 244h860v19H70Z" fill="#647a82"/>${sceneWindows(110,290,20,4,39,36,'#acd5d6')}<path d="M430 190h140v280H430Z" fill="#d2c3a3"/><path d="m418 190 82-68 82 68Z" fill="#5d737e"/><circle cx="500" cy="231" r="27" fill="#e7dfbf" stroke="#6d827e" stroke-width="5"/><path d="M500 212v20l12 10" fill="none" stroke="#5c7070" stroke-width="4"/><path d="M465 470v-100h70v100" fill="#536f75"/><path d="M0 700 450 465h100l450 235Z" fill="#a5a79a"/><path d="M100 600h800M175 545h650" stroke="#d7cfb3" stroke-width="3"/>${sceneTree(60,495,.9)}${sceneTree(900,510,1.05)}<path d="M765 565v-175h85v85h-85m40 0v90" fill="none" stroke="#708786" stroke-width="5"/>`;
 if(id===3)scene=`<path d="M0 470H1000V700H0Z" fill="#8b9b95"/><path d="M50 470V300l95-55v55l100-55v55l100-55v225Z" fill="#829696"/><path d="M375 470V250h330v220Z" fill="#a3a38c"/>${sceneWindows(401,282,7,3,40,37,'#d6debe')}<path d="M400 250V110h40v140m80 0V70h50v180m80 0V135h40v115" fill="#778d92"/><path d="M795 470V310a60 60 0 0 1 120 0v160Z" fill="#9aaeb0"/><path d="M795 340h120m-120 65h120" fill="none" stroke="#627e83" stroke-width="7"/><path d="M665 440v-80h130M655 460v-130h160" fill="none" stroke="#5c7d82" stroke-width="13"/><path d="M80 550h280v105H80Z" fill="#6b8781"/>${sceneWindows(100,568,6,1,40,50,'#a3b3a0')}<path d="m380 700 300-210M430 700 710 490" stroke="#5f7774" stroke-width="8"/><g fill="#d9dfcf" opacity=".2"><ellipse cx="540" cy="72" rx="56" ry="22"/><ellipse cx="570" cy="35" rx="73" ry="28"/></g>`;
 if(id===4)scene=`<path d="M0 475H1000V700H0Z" fill="#a3aa96"/><path d="M285 480V280l210-140 210 140v200Z" fill="#b4b09b"/><path d="m263 280 232-165 232 165-22 15-210-140-210 140Z" fill="#647d83"/><path d="M160 480V210h120v270m430 0V210h120v270Z" fill="#bfc1a8"/><path d="m148 210 72-145 72 145m406 0 72-145 72 145" fill="#5a7680"/><path d="M495 80v-50m-18 18h36" stroke="#657b77" stroke-width="7"/><circle cx="495" cy="285" r="51" fill="#6b8e9a" stroke="#d9cba4" stroke-width="9"/><path d="M495 239v92m-45-46h91m-77-32 63 64m-63 0 63-64" stroke="#b6b9a5" stroke-width="5"/><path d="M450 480v-70a45 45 0 0 1 90 0v70" fill="#536e72"/><path d="M200 315v-60a20 20 0 0 1 40 0v60m510 0v-60a20 20 0 0 1 40 0v60" fill="#648b91"/><path d="m295 700 160-220h80l180 220" fill="#bebba2"/><path d="M360 615h290M390 565h220M420 520h140" stroke="#8d9c8c" stroke-width="5"/>${sceneTree(90,530,1.2)}${sceneTree(890,530,1.2)}${sceneLantern(330,385)}${sceneLantern(680,385)}`;
 if(id===5)scene=`<path d="M0 320q140-140 300 0t330-20 370 0V700H0Z" fill="#73997d"/><path d="M0 440q190-140 380-20t310-30 310 30V700H0Z" fill="#5f896f"/>${[[-20,640,2.4],[120,500,1.6],[285,450,1.1],[390,420,.8],[660,440,1],[770,490,1.4],[960,650,2.6]].map(([x,y,s])=>sceneTree(x,y,s,x<400?'#537f65':'#4f7b65')).join('')}<path d="M300 700 480 415h55L740 700Z" fill="#c1b68e"/><path d="M400 700 500 430h12L590 700" fill="#d8c79d" opacity=".45"/><path d="M75 610q100-80 220 20m415 0q120-80 260-15" fill="none" stroke="#426d56" stroke-width="45"/><g fill="#d6d7a9" opacity=".5"><ellipse cx="450" cy="470" rx="70" ry="8"/><ellipse cx="550" cy="565" rx="100" ry="10"/></g>`;
 if(id===6)scene=`<path d="M0 375q160-70 350 0t350 0 300 0v325H0Z" fill="#6f9f87"/>${sceneTree(100,405,.95)}${sceneTree(235,400,.7)}${sceneTree(820,400,.9)}${sceneTree(950,440,1.1)}<path d="M0 520q180-150 430-125 230-35 570 115v190H0Z" fill="#6eafba"/><path d="M0 555q200-130 480-95 300-30 520 100v140H0Z" fill="#76bbc1"/><g fill="none" stroke="#bfd8c7" stroke-width="3" opacity=".65"><path d="M200 500h110m200 20h200M90 590h200m50 25h210m90-30h240M120 665h230m190-10h230"/></g><path d="M75 455h210v-12H75Z" fill="#d2c0a2"/><path d="M95 444v-65h155v65" fill="none" stroke="#8a8170" stroke-width="10"/><path d="m65 375 105-85 105 85Z" fill="#597d87"/><path d="M95 480v40m165-40v35" stroke="#7d8d7b" stroke-width="8"/><path d="M0 700v-65q180-100 360-22L530 700Z" fill="#c5b795"/><path d="m0 642 250-45 210 90" fill="none" stroke="#d8cba9" stroke-width="8"/><path d="M690 700v-120m15 120 15-145m-45 145-10-110m120 110 5-95m-110 15-10-65m50 70 10-70" stroke="#5b8a65" stroke-width="7"/><g fill="#779653"><ellipse cx="390" cy="560" rx="24" ry="7"/><ellipse cx="440" cy="580" rx="19" ry="6"/><ellipse cx="750" cy="620" rx="35" ry="9"/></g>`;
 if(id===7)scene=`<path d="M0 390H1000V700H0Z" fill="#82b6c0"/><path d="M0 480 680 425 830 700H0Z" fill="#9fa79d"/><path d="m0 505 685-55 135 250" fill="none" stroke="#d2c8ab" stroke-width="12"/><path d="M100 460V120h20v340m-50-300h460v15H70m45-45 340 45m0 0v120" fill="none" stroke="#688b93" stroke-width="9"/><path d="M435 295h40v35h-40Z" fill="#677c7e"/><path d="M60 530h200v90H60Z" fill="#6a9699"/><path d="M280 490h180v90H280Z" fill="#ad9b82"/><path d="M280 397h180v90H280Z" fill="#8d9d86"/><path d="M70 438h185v88H70Z" fill="#a2b3a1"/><path d="M80 445v70m25-70v70m25-70v70m25-70v70m25-70v70m25-70v70m25-70v70" stroke="#748d83" stroke-width="3"/><path d="m725 475 245-15-25 60H745Z" fill="#596f7c"/><path d="M790 460v-90h110v90" fill="#d1d1b8"/>${sceneWindows(805,385,3,1,29,31,'#7799a3')}<path d="M640 590h230m-10 55h130m-270-95h70" stroke="#d1d9bc" stroke-width="3"/>`;
 if(id===8)scene=`<path d="M0 475h1000v225H0Z" fill="#9cae9e"/><path d="M165 470V175h270v295m155 0V175h270v295" fill="#a5b4b0"/>${sceneWindows(190,205,6,7,37,34,'#e6d2aa')}${sceneWindows(615,205,6,7,37,34,'#d2dfc8')}<path d="M435 470V135h155v335Z" fill="#c5bba5"/><path d="M425 130h175v20H425Z" fill="#607c89"/><text x="512" y="195" text-anchor="middle" fill="#526d78" font-family="sans-serif" font-size="25" letter-spacing="5">HOTEL</text>${sceneWindows(465,225,3,4,35,35,'#8faeb0')}<path d="M470 470v-85h85v85" fill="#577e89"/><path d="M400 390h215l-25-40H425Z" fill="#73888a"/><path d="M0 700 470 470h85l445 230Z" fill="#bdb7a6"/><ellipse cx="200" cy="590" rx="110" ry="38" fill="#7aabae" stroke="#d3c9ad" stroke-width="10"/><path d="M200 585v-50m-30 25q30-80 60 0" fill="none" stroke="#b5d2cc" stroke-width="5"/>${sceneTree(70,490,1.1)}${sceneTree(920,510,1.1)}${sceneLantern(380,365)}${sceneLantern(665,365)}`;
 return `<svg class="forest region-scene" data-scene="${id}" viewBox="0 0 1000 700" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="scene-sky" x2="0" y2="1"><stop stop-color="${sky}"/><stop offset="1" stop-color="${horizon}"/></linearGradient><linearGradient id="scene-depth" x2="0" y2="1"><stop stop-color="#f4e3bd" stop-opacity=".03"/><stop offset="1" stop-color="#244653" stop-opacity=".12"/></linearGradient></defs><rect width="1000" height="700" fill="url(#scene-sky)"/><circle cx="720" cy="135" r="55" fill="#f6e6b6" opacity=".55"/><g fill="#eef1d9" opacity=".25"><ellipse cx="185" cy="120" rx="130" ry="20"/><ellipse cx="420" cy="175" rx="105" ry="14"/></g>${distant}${scene}<rect width="1000" height="700" fill="url(#scene-depth)"/></svg>`;
}
